# frozen_string_literal: true
require_relative 'work_date_tools_components'

def work_symbol(name)
  paths = {
    'days'=>'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-11 5 2 2 4-4"/>',
    'hours'=>'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
    'rest'=>'<path d="M4 15h16M6 15V9a3 3 0 0 1 3-3h6a3 3 0 0 1 3 3v6M5 15v4m14-4v4M9 10h6"/>',
    'short'=>'<path d="M5 4h14M5 20h14M7 4v3l5 5-5 5v3m10-16v3l-5 5 5 5v3M9 18h6"/>',
    'download'=>'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
    'print'=>'<path d="M7 8V3h10v5M7 17H4V9h16v8h-3M7 14h10v7H7zM17 11h.01"/>',
    'difference'=>'<rect x="3" y="4" width="7" height="7" rx="2"/><rect x="14" y="13" width="7" height="7" rx="2"/><path d="M14 7h7m-3-3 3 3-3 3M3 17h7m-7 0 3-3m-3 3 3 3"/>',
    'add'=>'<circle cx="8" cy="8" r="5"/><circle cx="16" cy="16" r="5"/><path d="M8 5v6M5 8h6m2 8h6"/>',
    'swap'=>'<path d="M4 8h16m-4-4 4 4-4 4M20 16H4m4-4-4 4 4 4"/>',
    'calculate'=>'<rect x="5" y="2" width="14" height="20" rx="3"/><path d="M8 6h8M8 11h1m6 0h1m-8 4h1m6 0h1m-8 4h1m6 0h1"/>',
    'copy'=>'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M15 8V3H3v13h5"/>',
    'link'=>'<path d="m9 15 6-6m-4-3 2-2a5 5 0 0 1 7 7l-2 2M6 11l-2 2a5 5 0 0 0 7 7l2-2"/>'
  }
  %(<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">#{paths.fetch(name)}</svg>)
end

def work_hero_markup(heading, description, year, month)
  %(<header class="work-hero"><div class="work-hero-copy"><span class="work-kicker">LATVIJA · 2027–2030</span><h1>#{h(heading)}</h1><p>#{h(description)}</p><div class="work-hero-actions"><a href="#darba-periods" class="work-primary">Sākt aprēķinu <span aria-hidden="true">↓</span></a><a href="#darba-parskats">Gada pārskats <span aria-hidden="true">↗</span></a></div><div class="work-hero-points"><span>Oficiālie svētki</span><span>Pirmssvētku stundas</span><span>Tūlītējs aprēķins</span></div></div><div class="work-hero-art" aria-hidden="true"><svg viewBox="0 0 410 295" fill="none"><defs><linearGradient id="work-paper" x1="100" y1="40" x2="300" y2="260" gradientUnits="userSpaceOnUse"><stop stop-color="#fffefa"/><stop offset="1" stop-color="#e7d7c7"/></linearGradient><linearGradient id="work-cover" x1="120" y1="30" x2="280" y2="150" gradientUnits="userSpaceOnUse"><stop stop-color="#a84a5d"/><stop offset="1" stop-color="#661a32"/></linearGradient><linearGradient id="work-metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#eed7a8"/><stop offset=".45" stop-color="#b48644"/><stop offset=".65" stop-color="#fff0c9"/><stop offset="1" stop-color="#a47535"/></linearGradient><filter id="work-shadow" x="-30%" y="-30%" width="170%" height="180%"><feDropShadow dx="0" dy="11" stdDeviation="11" flood-color="#4b2630" flood-opacity=".17"/></filter></defs><ellipse cx="206" cy="266" rx="145" ry="15" fill="#71414a" opacity=".08"/><g transform="translate(81 24) rotate(-9 130 125)" filter="url(#work-shadow)"><rect x="7" y="15" width="240" height="224" rx="20" fill="#c9b7a6"/><rect x="3" y="9" width="240" height="224" rx="20" fill="#e5d8c6" stroke="#ccbba9"/><rect width="240" height="224" rx="20" fill="url(#work-paper)" stroke="#fdf8f0" stroke-width="2"/><path d="M0 20C0 9 9 0 20 0h200c11 0 20 9 20 20v42H0Z" fill="url(#work-cover)"/><path d="M20 3h200" stroke="#e2a5ac" stroke-opacity=".5"/><g stroke="url(#work-metal)" stroke-width="10" stroke-linecap="round"><path d="M55-8v28M185-8v28"/></g><g fill="#dec9be"><rect x="24" y="88" width="31" height="23" rx="5"/><rect x="67" y="88" width="31" height="23" rx="5"/><rect x="110" y="88" width="31" height="23" rx="5"/><rect x="153" y="88" width="31" height="23" rx="5"/><rect x="24" y="123" width="31" height="23" rx="5"/><rect x="67" y="123" width="31" height="23" rx="5"/><rect x="153" y="123" width="31" height="23" rx="5"/><rect x="24" y="158" width="31" height="23" rx="5"/><rect x="67" y="158" width="31" height="23" rx="5"/><rect x="110" y="158" width="31" height="23" rx="5"/><rect x="153" y="158" width="31" height="23" rx="5"/></g><rect x="109" y="120" width="35" height="29" rx="7" fill="#872740"/><path d="m117 134 6 6 12-13" stroke="#fff7e6" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M25 203h127" stroke="#b9a193" stroke-width="3" stroke-linecap="round"/></g><g transform="translate(266 161)" filter="url(#work-shadow)"><circle cx="39" cy="42" r="49" fill="#6d293c"/><circle cx="37" cy="37" r="47" fill="url(#work-metal)"/><circle cx="37" cy="37" r="40" fill="#fffcf3" stroke="#f5e6d1" stroke-width="2"/><path d="M37 4v5m0 56v5M4 37h5m56 0h5" stroke="#a48c79" stroke-width="2"/><path d="M37 15v23l14 10" stroke="#723044" stroke-width="4" stroke-linecap="round"/><circle cx="37" cy="37" r="4" fill="#a45365"/></g></svg></div></header>)
end

def work_calendar_cells(rows, selected)
  blank = Array.new(Date.parse(rows.first.fetch('date')).cwday - 1, '<span aria-hidden="true"></span>').join
  blank + rows.map do |row|
    day = Date.parse(row['date']).day
    label = "#{hub_date(row['date'])} · #{row['work'] ? "#{row['hours']} h" : 'Brīvdiena'}"
    %(<button type="button" class="work-day is-#{row['kind']}" data-work-day="#{row['date']}" aria-label="#{h(label)}" aria-pressed="#{row['date'] == selected}"><span>#{day}</span><small>#{row['work'] ? "#{row['hours']} h" : '—'}</small></button>)
  end.join
end

def work_print_gallery(year, month=nil)
  %(<section class="content-card print-section" data-print-type="#{month ? 'work' : 'work-year'}" data-print-year="#{year}" data-print-month="#{month}"><h2>Darba kalendārs drukāšanai</h2><p>15 dizaini · PDF un attēls. Veidnēs ir pamata piecu darba dienu kalendārs; sava pielāgotā grafika datus lejupielādē CSV vai izdrukā mēneša skatā.</p>#{widget('print')}</section>)
end

def work_schedule_markup
  %(<form class="work-settings" data-work-settings><fieldset><legend>Darba dienas nedēļā</legend><div class="work-weekdays">#{%w[P O T C Pk S Sv].each_with_index.map { |label,i| %(<label><input type="checkbox" name="weekday" value="#{i+1}"#{i<5 ? ' checked' : ''} aria-label="#{%w[Pirmdiena Otrdiena Trešdiena Ceturtdiena Piektdiena Sestdiena Svētdiena][i]}"><span>#{label}</span></label>) }.join}</div></fieldset><label class="work-hours">Stundas dienā<span class="work-hours-input"><input type="number" name="hours" value="8" min="0.5" max="24" step="0.5" required><span>h</span></span></label><div class="work-toggles"><label><input type="checkbox" name="holidays" checked><span>Atņemt svētku brīvdienas</span></label><label><input type="checkbox" name="shorten" checked><span>Pirms svētkiem saīsināt par 1 h</span></label></div><button type="reset" class="work-reset">Atiestatīt</button><details class="work-overrides"><summary>Mana darba devēja īpašie datumi</summary><p>Pārceltās darba dienas netiek piemērotas automātiski. Ievadi savas papildu darba dienas un brīvdienas formātā GGGG-MM-DD, atdalot tās ar komatu. Tās aizstāj pamatgrafiku.</p><div><label>Papildu brīvdienas<textarea name="off" rows="2" placeholder="2027-06-25"></textarea></label><label>Papildu darba dienas<textarea name="on" rows="2" placeholder="2027-06-19"></textarea></label></div></details><p class="work-setting-note" data-work-setting-note>8 stundas dienā · 5 darba dienas nedēļā · pirmssvētku dienās 7 h.</p><p class="work-error" data-work-error role="alert" hidden></p></form>)
end

def work_calendar_markup(year=2027, month=nil)
  result=WORK_CALENDAR_SNAPSHOTS.fetch(year.to_s)
  selected_month=month || 1
  selected=result.fetch('months')[selected_month-1]
  initial_date=selected.fetch('from')
  year_links=(2027..2030).map { |y| %(<a href="/darba-dienu-kalendars/#{y}/" data-work-year="#{y}"#{year==y ? ' aria-current="page"' : ''}>#{y}</a>) }.join
  metrics=[['work','days','Darba dienas'],['hours','hours','Plānotās stundas'],['rest','rest','Brīvdienas'],['shortened','short','Saīsinātas dienas']].map do |key,icon,label|
    %(<article class="work-stat work-stat--#{key}"><span class="work-stat-icon">#{work_symbol(icon)}</span><div><strong data-work-total="#{key}">#{result[key]}</strong><span>#{label}</span></div></article>)
  end.join
  months=result.fetch('months').map do |item|
    n=item.fetch('month')
    %(<a class="work-month-card#{n==selected_month ? ' is-selected' : ''}" href="/darba-dienu-kalendars/#{year}/#{SLUGS[n-1]}/" data-work-pick-month="#{n}"><div class="work-month-top"><span>#{format('%02d',n)}</span>#{ui_icon("month-#{n}")}<span aria-hidden="true">↗</span></div><h3>#{MONTHS[n-1].capitalize}</h3><div class="work-month-value"><strong data-month-value="work">#{item['work']}</strong><span>#{item['work'] % 10 == 1 && item['work'] % 100 != 11 ? 'darba diena' : 'darba dienas'}</span></div><div class="work-month-bar" aria-hidden="true"><span style="width:#{(100.0*item['work']/item['days']).round(2)}%"></span></div><div class="work-month-foot"><span><b data-month-value="hours">#{item['hours']}</b> h</span><span><b data-month-value="rest">#{item['rest']}</b> brīvdienas</span></div></a>)
  end.join
  table=result.fetch('months').map { |item| n=item['month']; %(<tr data-work-table-month="#{n}"><th scope="row"><a href="/darba-dienu-kalendars/#{year}/#{SLUGS[n-1]}/">#{MONTHS[n-1].capitalize}</a></th>#{%w[days work hours rest shortened excludedHolidays].map { |key| %(<td data-table-value="#{key}">#{item[key]}</td>) }.join}</tr>) }.join
  %(<div class="work-experience" data-work-calendar data-work-year="#{year}" data-work-month="#{selected_month}">
  #{work_date_tool_markup(year,month,result,selected)}
  <section class="work-overview" id="darba-parskats" aria-labelledby="work-overview-title"><div class="work-section-heading"><div><span class="work-kicker">GADA PĀRSKATS</span><h2 id="work-overview-title">#{year}. gads. Tavs darba ritms.</h2><p>Kalkulatorā izvēlētais darba grafiks. Atver mēnesi un apskati katru dienu.</p></div><nav class="work-year-tabs" aria-label="Darba kalendāra gads">#{year_links}</nav></div><div class="work-stats">#{metrics}</div><p class="work-total-caption" data-work-caption>#{result['days']} kalendārās dienas · #{result['excludedHolidays']} svētku brīvdienas atlasītajās darba dienās</p>
<div class="work-month-cards" aria-label="Darba dienas pa mēnešiem">#{months}</div><details class="work-table-details"><summary>Skatīt visu mēnešu skaitļus tabulā</summary><div class="work-table-scroll" role="region" aria-label="Darba dienu un stundu tabula" tabindex="0"><table><thead><tr><th scope="col">Mēnesis</th><th scope="col">Dienas</th><th scope="col">Darba dienas</th><th scope="col">Stundas</th><th scope="col">Brīvdienas</th><th scope="col">Saīsinātas</th><th scope="col">Atņemtie svētki</th></tr></thead><tbody>#{table}</tbody><tfoot><tr><th scope="row">Gadā kopā</th>#{%w[days work hours rest shortened excludedHolidays].map { |key| %(<td data-work-table-total="#{key}">#{result[key]}</td>) }.join}</tr></tfoot></table></div></details><div class="work-overview-bottom"><p>Svētki nedēļas nogalē netiek atņemti vēlreiz. Atceres dienas nemaina darba dienu skaitu.</p><button type="button" data-work-csv="year">#{work_symbol('download')} Gada dati · CSV</button></div></section>
  <section class="work-month-explorer" id="darba-menesis" aria-labelledby="work-month-title"><div class="work-section-heading"><div><span class="work-kicker">MĒNESIS TUVPLĀNĀ</span><h2 id="work-month-title">#{MONTHS[selected_month-1].capitalize} #{year}</h2><p>Spied uz dienas, lai redzētu darba laiku un svētku nosaukumu.</p></div><button type="button" data-work-print>#{work_symbol('print')} Drukāt mēnesi</button></div><div class="work-month-layout"><div class="work-calendar"><div class="work-calendar-nav"><button type="button" data-work-step="-1" aria-label="Iepriekšējais darba kalendāra mēnesis"#{selected_month==1 ? ' disabled' : ''}>←</button><label><span class="sr-only">Darba kalendāra mēnesis</span><select data-work-month-select>#{(1..12).map { |n| %(<option value="#{n}"#{n==selected_month ? ' selected' : ''}>#{MONTHS[n-1].capitalize} #{year}</option>) }.join}</select></label><button type="button" data-work-step="1" aria-label="Nākamais darba kalendāra mēnesis"#{selected_month==12 ? ' disabled' : ''}>→</button><a data-work-month-page href="/darba-dienu-kalendars/#{year}/#{SLUGS[selected_month-1]}/">Mēneša lapa ↗</a></div><div class="work-calendar-weekdays" aria-hidden="true">#{%w[P O T C Pk S Sv].map { |day| "<span>#{day}</span>" }.join}</div><div class="work-calendar-grid" data-work-calendar-grid>#{work_calendar_cells(selected['rows'],initial_date)}</div><div class="work-legend"><span class="legend-work">Darba diena</span><span class="legend-short">Saīsināta diena</span><span class="legend-holiday">Svētku brīvdiena</span><span class="legend-rest">Brīvdiena</span></div></div><aside class="work-day-detail" data-work-day-detail aria-live="polite"><span class="work-kicker">IZVĒLĒTAIS DATUMS</span><h3>#{hub_date(initial_date)}</h3><strong>#{selected['rows'].first['work'] ? 'Darba diena' : 'Brīvdiena'}</strong><p>#{selected['rows'].first['holiday'].map { |holiday| h(holiday['title']) }.join('<br>')}</p></aside></div><details class="work-month-dates"><summary>Šī mēneša svētki un saīsinātās dienas</summary><ul data-work-month-dates>#{selected['rows'].select { |row| !row['holiday'].empty? || row['shortened'] }.map { |row| %(<li><time datetime="#{row['date']}">#{hub_date(row['date'])}</time><span>#{row['shortened'] ? "Saīsināta darba diena · #{row['hours']} h" : row['holiday'].map { |holiday| h(holiday['title']) }.join('; ')}</span></li>) }.join}</ul></details></section>
  <nav class="work-related" aria-label="Darba plānošanas rīki"><a href="/atvalinajuma-planotajs/">#{ui_icon('vacation')}<span><strong>Atvaļinājuma plānotājs</strong><small>Savieno svētkus ar atpūtu.</small></span><span aria-hidden="true">↗</span></a><a href="/svetku-dienas/#{year}/">#{ui_icon('gift')}<span><strong>#{year}. gada svētki</strong><small>Visi Latvijas svētku datumi.</small></span><span aria-hidden="true">↗</span></a><a href="/mainu-grafiks/">#{ui_icon('shift')}<span><strong>Maiņu grafiks</strong><small>Plāns mainīgam darba ciklam.</small></span><span aria-hidden="true">↗</span></a></nav>
  <section class="work-method" id="darba-metodika"><div><span class="work-kicker">SKAIDRS APRĒĶINS</span><h2>Kā skaitām dienas un stundas?</h2></div><div><details><summary>Kā skaitām starpību starp datumiem?</summary><p>Dienu starpību skaitām pēc kalendāra datumiem, nevis pagājušajām pulksteņa stundām. Var ieskaitīt abus robeždatumus. Pilni mēneši un atlikušās dienas rāda kalendāra starpību; tā netiek pārvērsta vienāda garuma 30 dienu mēnešos.</p></details><details><summary>Kas notiek, pieskaitot mēnesi 31. janvārim?</summary><p>Ja nākamajā mēnesī attiecīgās dienas nav, izmantojam tā pēdējo dienu: 2027. gada 31. janvāris + 1 mēnesis ir 28. februāris, bet 2028. gadā — 29. februāris. Negatīvs skaitlis atņem laiku. Datumu starpība un pārbīde pieejama 1900.–2100. gadam; Latvijas darba dienu un svētku aprēķins — 2027.–2030. gadam.</p></details><details><summary>Kā saglabāt vai kopīgot rezultātu?</summary><p>“Kopēt rezultātu” saglabā teksta kopsavilkumu starpliktuvē. “Kopēt saiti” izveido saiti ar taviem datumiem un iestatījumiem. Saņēmējs redzēs tos pašus ievaddatus; savas privātās piezīmes saitē neiekļauj. CSV saglabā faktiskās darba perioda dienas un stundas.</p></details><details><summary>Kuri svētki ietekmē darba dienu skaitu?</summary><p>Atņemam likumā noteiktās svētku brīvdienas, kas iekrīt izvēlētajās darba dienās. Ja 4. maijs, 18. novembris vai Vispārējo latviešu dziesmu un deju svētku noslēguma diena ir nedēļas nogalē, piemērojam likumā paredzēto nākamo brīvdienu. 2028. gada Dziesmu un deju svētku noslēgums ir 9. jūlijā; papildu brīvdiena ir 10. jūlijā.</p></details><details><summary>Kā aprēķinām pirmssvētku stundas?</summary><p>Ja saīsināšana ir ieslēgta, darba dienai tieši pirms likumā noteiktas svētku dienas atņemam vienu stundu. Parasta brīvdiena vai aizstājoša brīvdiena pati par sevi nerada saīsinājumu iepriekšējai darba dienai. Nepilnam darba laikam un individuāliem grafikiem pārbaudi līgumu un VDI skaidrojumu; saīsināšanu vari izslēgt.</p></details><details><summary>Vai te ir iekļautas pārceltās darba dienas?</summary><p>Pamataprēķinā nav automātisku darbdienu pārcelšanu. Savā iestādē vai uzņēmumā piemērojamos datumus ievadi sadaļā „Mana darba devēja īpašie datumi”. 2028.–2030. gada pamataprēķins izmanto pašlaik spēkā esošo svētku regulējumu; turpmāki normatīvo aktu grozījumi var mainīt rezultātus.</p></details><details><summary>Vai izvēlētais stundu skaits ir darba laika norma?</summary><p>Šis ir plānošanas aprēķins. Noklusējums ir pirmdiena–piektdiena, 8 stundas dienā, ar pirmssvētku saīsinājumu. Pielāgotās nedēļas dienas un stundas veido tavu izvēlēto modeli; tas automātiski nenosaka normālo darba laiku, algu, virsstundas vai maiņu darba normu.</p></details><div class="work-sources"><a href="https://likumi.lv/ta/id/26019-darba-likums" target="_blank" rel="noopener">Darba likums · 131., 133. un 135. pants ↗</a><a href="#{LAW}" target="_blank" rel="noopener">Svētku, atceres un atzīmējamās dienas ↗</a><a href="https://www.vdi.gov.lv/lv/darba-laiks" target="_blank" rel="noopener">VDI · darba laika skaidrojums ↗</a><a href="https://likumi.lv/ta/id/367734-par-xxviii-visparejo-latviesu-dziesmu-un-xviiideju-svetku-norises-laiku" target="_blank" rel="noopener">2028. gada Dziesmu un deju svētku norise ↗</a></div></div></section><p class="work-feedback" data-work-feedback role="status"></p></div>)
end
